def is_type_B(N):
    W = [False] * (N + 1)
    for n in range(N - 1, 0, -1):
        # W[n] is True if the player whose turn it is to move from state n wins.
        # The player who sees n can win if they can move to a state n' such that
        # the player who sees n' loses (W[n'] is False) or if they can move to N.
        can_win = False
        # Move to n+1
        if n + 1 == N:
            can_win = True
        elif n + 1 < N and W[n + 1] == False:
            can_win = True
        # Move to 2n
        if 2 * n == N:
            can_win = True
        elif 2 * n < N and W[2 * n] == False:
            can_win = True
        W[n] = can_win
    # After A writes 1, it is B's turn to move from state 1.
    # If W[1] is True, B wins, so N is type B.
    return W[1]

